homeFiles.projects/calibration-lab/lab-clio.yaml:
notes: "Lab gateway, forwarded to port 4000. Ask #research-computing for a key; export it as LAB_API_KEY."
targets:
  - id: lab
    runtime: openai-compat
    url: http://localhost:4000/v1
    defaultModel: gpt-oss-120b
    capabilities: { contextWindow: 131072 }
    auth: { apiKeyEnvVar: LAB_API_KEY }
chat: { target: lab }
fleet: { target: lab, model: gpt-oss-120b }
